#if UNITY_EDITOR
using System.IO;
using System.Text.RegularExpressions;
using TMPro;
using Unity.VectorGraphics.Editor;
using UnityEditor;
using UnityEngine;
using UnityEngine.TextCore;

namespace Zeitgeist {
    /// <summary>
    /// Turns the effect icon sheet (Assets/Art/Icons/EffectIcons.svg, generated by Tools/generate_card_art.py)
    /// into a TextMeshPro sprite asset and makes it TMP's default, so any text can use &lt;sprite name="death"&gt;.
    /// </summary>
    public static class EffectIconAtlasBuilder {
        private const string SheetPath = "Assets/Art/Icons/EffectIcons.svg";
        private const string SpriteAssetPath = "Assets/Art/Icons/EffectIcons.asset";
        private const int SheetTextureWidth = 1024;
        private const float IconCellSize = 128f; // Size of one icon cell in the SVG's own units

        // Each icon is a <g id="name" transform="translate(x y)"> in the sheet
        private static readonly Regex IconCell = new Regex("<g id=\"([a-z_]+)\" transform=\"translate\\((\\d+) (\\d+)\\)\">");
        private static readonly Regex ViewBox = new Regex("viewBox=\"0 0 (\\d+) (\\d+)\"");

        [MenuItem("Cards/Build Effect Icons")]
        public static void BuildEffectIcons() {
            if (!SvgImportSettings.Configure(SheetPath, SVGType.Texture2D, SheetTextureWidth)) {
                Debug.LogError($"Effect icon sheet not found at {SheetPath}. Run Tools/generate_card_art.py first.");
                return;
            }

            // A freshly changed import type may not be loadable until the import is forced to finish
            var texture = AssetDatabase.LoadAssetAtPath<Texture2D>(SheetPath);
            if (texture == null) {
                AssetDatabase.ImportAsset(SheetPath, ImportAssetOptions.ForceSynchronousImport);
                texture = AssetDatabase.LoadAssetAtPath<Texture2D>(SheetPath);
            }
            string svg = File.ReadAllText(SheetPath);
            var viewBox = ViewBox.Match(svg);
            float sheetHeight = float.Parse(viewBox.Groups[2].Value);
            float pixelsPerUnit = texture.width / float.Parse(viewBox.Groups[1].Value);

            var spriteAsset = LoadOrCreateSpriteAsset(texture);
            spriteAsset.spriteGlyphTable.Clear();
            spriteAsset.spriteCharacterTable.Clear();

            float cell = IconCellSize * pixelsPerUnit;
            uint index = 0;
            foreach (Match icon in IconCell.Matches(svg)) {
                float x = float.Parse(icon.Groups[2].Value) * pixelsPerUnit;
                float yFromTop = float.Parse(icon.Groups[3].Value);
                float y = (sheetHeight - yFromTop - IconCellSize) * pixelsPerUnit; // Texture rows start at the bottom

                // Icons sit slightly below the baseline and advance a little past their width, like a glyph
                var glyph = new TMP_SpriteGlyph {
                    index = index,
                    metrics = new GlyphMetrics(cell, cell, 0f, cell * 0.82f, cell * 1.08f),
                    glyphRect = new GlyphRect((int)x, (int)y, (int)cell, (int)cell),
                    scale = 1f,
                    atlasIndex = 0,
                };
                spriteAsset.spriteGlyphTable.Add(glyph);
                spriteAsset.spriteCharacterTable.Add(new TMP_SpriteCharacter(0xFFFE, glyph) { name = icon.Groups[1].Value, scale = 1f });
                index++;
            }

            spriteAsset.UpdateLookupTables();
            EditorUtility.SetDirty(spriteAsset);
            MakeDefaultSpriteAsset(spriteAsset);
            AssetDatabase.SaveAssets();
            Debug.Log($"Built {index} effect icons into {SpriteAssetPath}");
        }

        private static TMP_SpriteAsset LoadOrCreateSpriteAsset(Texture2D texture) {
            var spriteAsset = AssetDatabase.LoadAssetAtPath<TMP_SpriteAsset>(SpriteAssetPath);
            if (spriteAsset == null) {
                spriteAsset = ScriptableObject.CreateInstance<TMP_SpriteAsset>();
                AssetDatabase.CreateAsset(spriteAsset, SpriteAssetPath);

                var material = new Material(Shader.Find("TextMeshPro/Sprite")) { name = "EffectIcons Material" };
                AssetDatabase.AddObjectToAsset(material, spriteAsset);
                spriteAsset.material = material;
            }

            spriteAsset.spriteSheet = texture;
            spriteAsset.material.SetTexture(ShaderUtilities.ID_MainTex, texture);
            return spriteAsset;
        }

        private static void MakeDefaultSpriteAsset(TMP_SpriteAsset spriteAsset) {
            var settings = new SerializedObject(TMP_Settings.instance);
            settings.FindProperty("m_defaultSpriteAsset").objectReferenceValue = spriteAsset;
            settings.ApplyModifiedPropertiesWithoutUndo();
            EditorUtility.SetDirty(TMP_Settings.instance);
        }
    }
}
#endif
